const incoming = $input.all();

const ads = incoming.flatMap(item =>
  Array.isArray(item.json) ? item.json : [item.json]
);

return ads.map(ad => {
  const snapshot = ad.snapshot || {};
  const card = snapshot.cards?.[0] || {};

  return {
    json: {
      ad_id: ad.ad_archive_id || "",
      page_name: ad.page_name || "",
      title: card.title || snapshot.title || "",
      body: card.body || snapshot.body?.text || "",
      hook: card.title || snapshot.title || "",
      cta: card.cta_text || snapshot.cta_text || "",
      video_url: card.video_hd_url || "",
      ad_library_url: ad.ad_library_url || ""
    }
  };
});

const items = $input.all();

const results = items.map((item, index) => {

  // Gemini AI analysis extract cheyyunnu
  const analysis = item.json.content?.parts
    ?.map(part => part.text || "")
    .join("\n") || "";

  // Overall score kandupidikkunnu
  const match = analysis.match(
    /Overall\s+Creative\s+Score\s*[:\-]\s*(\d+(?:\.\d+)?)\s*\/\s*10/i
  );

  const score = match ? Number(match[1]) : 0;

  return {
    json: {
      ad_id: item.json.ad_id || "",
      page_name: item.json.page_name || "",
      title: item.json.title || "",
      hook: item.json.hook || item.json.title || "",
      body: item.json.body || "",
      cta: item.json.cta || "",
      video_url: item.json.video_url || "",
      ad_library_url: item.json.ad_library_url || "",
      ad_number: index + 1,
      overall_score: score,
      analysis: analysis
    }
  };
});

// Highest score first
results.sort(
  (a, b) => b.json.overall_score - a.json.overall_score
);

// Rank assign cheyyunnu
return results.map((item, index) => ({
  json: {
    rank: index + 1,
    ...item.json
  }
}));

const items = $input.all();

// All five ranked ads
const ads = items.map(item => ({
  rank: item.json.rank,
  ad_id: item.json.ad_id,
  page_name: item.json.page_name,
  title: item.json.title,
  hook: item.json.hook,
  body: item.json.body,
  cta: item.json.cta,
  ad_library_url: item.json.ad_library_url,
  overall_score: item.json.overall_score,
  analysis: item.json.analysis
}));

// Highest ranked ad
const bestAd = ads[0];

return [{
  json: {
    report_title: "MySivi Facebook Ads Intelligence Report",
    total_ads_analysed: ads.length,
    best_ad: bestAd,
    all_ads: ads,
    important_note: "Scores represent AI-based creative quality analysis, not actual conversions or ROAS. Video content was not analysed."
  }
}];
